package com.smartlibrary;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import com.smartlibrary.algorithms.string.*;import com.smartlibrary.algorithms.flow.*;import com.smartlibrary.algorithms.randomized.*;import com.smartlibrary.algorithms.parallel.*;import com.smartlibrary.algorithms.complexity.*;
class AlgorithmTests {@Test void stringAlgorithmsAgree(){String t="ababaabababa",p="aba";var k=KMP.search(t,p).positions();assertEquals(k,ZFunction.search(t,p).positions());assertEquals(k,RabinKarp.search(t,p).positions());assertEquals(List.of(0,2,5,7,9),k);}@Test void suffixArrayAndAutomaton(){String s="banana";int[] sa=SuffixArray.build(s);assertEquals(6,sa.length);assertTrue(new SuffixAutomaton(s).contains("nan"));assertFalse(new SuffixAutomaton(s).contains("xyz"));}@Test void maxFlow(){int[][] c={{0,3,2,0},{0,0,1,2},{0,0,0,3},{0,0,0,0}};assertEquals(5,EdmondsKarp.maxFlow(c,0,3));}@Test void randomizedSort(){int[] a={4,1,9,1,-3};RandomizedQuickSort.sort(a,1);assertArrayEquals(new int[]{-3,1,1,4,9},a);}@Test void parallelPrefixMatches(){int[] a={1,2,3,4,5};assertArrayEquals(ParallelPrefixSum.sequential(a),ParallelPrefixSum.parallel(a));}@Test void vertexCoverValid(){int[][] e={{0,1},{1,2},{2,3}};var c=Optimization.vertexCoverApprox(4,e);assertTrue(Optimization.isVertexCover(c,e));}}
